package com.example.editor.remote.auth;

import java.util.List;
import com.example.editor.remote.storage.RemoteStorageProviderType;

/**
 * Public, secret-free provider registration material generated by HYDRA.
 * It contains only values that may safely be copied into a provider console.
 */
public record RemoteOAuthRegistrationKit(
        RemoteStorageProviderType provider,
        String displayName,
        String administrationUrl,
        String applicationType,
        String applicationNameSuggestion,
        String clientIdLabel,
        String callbackUrl,
        boolean callbackMustBeRegistered,
        boolean pkceRequired,
        boolean deviceFlowSupported,
        boolean deviceFlowPreferred,
        boolean serverCredentialRequired,
        String serverCredentialEnvironmentVariable,
        List<String> scopes) {
    /** Descripción: Normaliza la ficha pública de registro y evita exponer colecciones mutables. Entradas: campos públicos del proveedor; nunca incluye secretos. Salida: deja una ficha inmutable apta para mostrarse o descargarse. */
    public RemoteOAuthRegistrationKit {
        displayName=displayName==null?"":displayName;
        administrationUrl=administrationUrl==null?"":administrationUrl;
        applicationType=applicationType==null?"":applicationType;
        applicationNameSuggestion=applicationNameSuggestion==null?"HYDRA":applicationNameSuggestion;
        clientIdLabel=clientIdLabel==null?"Client ID":clientIdLabel;
        callbackUrl=callbackUrl==null?"":callbackUrl;
        serverCredentialEnvironmentVariable=serverCredentialEnvironmentVariable==null?"":serverCredentialEnvironmentVariable;
        scopes=scopes==null?List.of():List.copyOf(scopes);
    }
}
